<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfilePictureUrlAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfilePictureUrlAccessor trait.
 *
 * Covers null default, string/VO assignment via withPictureUrl,
 * getPictureUrl/pictureUrl accessors, and isPictureUrlChanged with/without original.
 */
class UserProfilePictureUrlAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withPictureUrl creates a new instance with the PictureUrl set
     * from a string value, and getPictureUrl returns the primitive string.
     */
    public function testWithPictureUrlFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePictureUrlAccessorUnitTest();

        // Act
        $result = $holder->withPictureUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getPictureUrl());
    }
    /**
     * Asserts that withpictureUrl has access to the value object
     * from a string value, and getPictureUrl returns the primitive string.
     */
    public function testWithPictureUrlFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePictureUrlAccessorUnitTest();

        // Act
        $result = $holder->withPictureUrl('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->pictureUrl()->value());
    }
    public function testChangedPictureUrl(): void
    {
        // Arrange
        $holder = new ImplWithUserProfilePictureUrlAccessorUnitTest();
        $original = $holder->withPictureUrl('one');
        $same = $holder->withPictureUrl('one');
        $modified = $holder->withPictureUrl('other');

        // Act
        $unchanged = $holder->isPictureUrlChanged();
        $withSame = $original->isPictureUrlChanged($same);
        $withDiferent = $original->isPictureUrlChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfilePictureUrlAccessorUnitTest
{
    use UserProfilePictureUrlAccessor;
}
